package com.medtrack.shipment.entity; import com.medtrack.shared.model.BaseEntity; import com.medtrack.transfer.entity.StockTransfer; import com.medtrack.warehouse.entity.Warehouse; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="shipments") public class Shipment extends BaseEntity {@Column(name="shipment_number",nullable=false,unique=true)private String shipmentNumber;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="transfer_id",nullable=false,unique=true)private StockTransfer transfer;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="origin_warehouse_id",nullable=false)private Warehouse origin;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="destination_warehouse_id",nullable=false)private Warehouse destination;@Column(name="carrier_name",nullable=false)private String carrierName;@Column(name="tracking_number",nullable=false,unique=true)private String trackingNumber;private String driverName;private String driverPhone;private String vehicleNumber;@Enumerated(EnumType.STRING)@Column(nullable=false)private ShipmentStatus status=ShipmentStatus.PREPARING;private Instant estimatedDeparture;private Instant actualDeparture;@Column(nullable=false)private Instant estimatedArrival;private Instant actualArrival;@OneToMany(mappedBy="shipment",cascade=CascadeType.ALL,orphanRemoval=true)private List<ShipmentItem> items=new ArrayList<>();protected Shipment(){}public Shipment(String n,StockTransfer t,String carrier,String tracking,String driver,String phone,String vehicle,Instant eta){shipmentNumber=n;transfer=t;origin=t.getSourceWarehouse();destination=t.getDestinationWarehouse();carrierName=carrier;trackingNumber=tracking;driverName=driver;driverPhone=phone;vehicleNumber=vehicle;estimatedArrival=eta;}public void addItem(ShipmentItem item){item.setShipment(this);items.add(item);}public void dispatch(){status=ShipmentStatus.DISPATCHED;actualDeparture=Instant.now();}public void deliver(){status=ShipmentStatus.DELIVERED;actualArrival=Instant.now();}public void cancel(){status=ShipmentStatus.CANCELLED;}public ShipmentStatus getStatus(){return status;}public StockTransfer getTransfer(){return transfer;}public Warehouse getOrigin(){return origin;}public Warehouse getDestination(){return destination;}public String getShipmentNumber(){return shipmentNumber;}public String getCarrierName(){return carrierName;}public String getTrackingNumber(){return trackingNumber;}public List<ShipmentItem> getItems(){return items;} }

